import json, os, sys
D = os.path.dirname(os.path.abspath(__file__))
PREFIX = "Flat vector cartoon sticker art for a cute 2D side-scrolling mobile game: thick uniform dark-purple outlines (#2b2233) around every shape, flat color fills with exactly one hard-edged cel-shade step, no gradients, no texture, warm sunset palette of coral, peach, cream, lavender and teal accents, clean bold graphic shapes readable at small size, strict side view orthographic elevation, transparent background, absolutely no text, no letters, no numbers, no digits, no logos, no brand trade dress."
TAIL = " One single isolated game obstacle prop, centered on the canvas with generous empty transparent margin, nothing else in the image: no ground line, no floor, no cast shadow, no drop shadow, no background scenery, no sky."
P = {
 "filebox": ("1:1", "Subject: a stack of exactly two brown cardboard file storage boxes, one sitting squarely on top of the other, drawn in pure flat side elevation with NO perspective: only the flat front face of each box is visible, no top face, no side face. Each box is a long low rectangle exactly TWICE as wide as it is tall, with a slightly overhanging lid band at its top, a strip of cream packing tape running vertically over the lid band, and a small oval hand-hold cutout. Plain kraft-brown cardboard, no labels, no writing. The whole two-box stack is almost square (8 wide by 9 tall)."),
 "chair": ("1:1", "Subject: a rolling office chair in pure flat side profile facing right, no perspective, with these proportions (total height 10 units, total width 9 units): at the bottom a star base seen from the side, 9 units wide, with exactly three small dark caster wheels visible (left end, center, right end); a tall chrome gas-lift column 3 units tall rising from the center; a teal padded seat cushion 6 units deep and 1.5 units thick; a LOW teal backrest at the left end of the seat rising only 2.5 units above the seat, connected by a short dark bracket. No armrests. The seat is noticeably narrower than the wheel base."),
 "scaffold": ("3:4", "Subject: one section of construction scaffolding in flat front elevation, built from grey metal pipes: exactly two vertical uprights at the far left and far right, horizontal ledgers at the top, middle and bottom, and one diagonal brace; a green mesh safety net with a fine diamond net pattern hangs from the top ledger on small rings and fills the frame; along the bottom edge a horizontal board painted with diagonal yellow and black warning stripes. Proportions: the whole silhouette is 3 units wide by 4 units tall, i.e. its width is three quarters of its height — a fairly wide panel, not a narrow tower."),
 "shopbar": ("3:4", "Subject: a low-hanging street shop sign obstacle, composed from top to bottom: at the very top, the front edge of a fabric awning with red and cream vertical stripes and a scalloped lower edge spanning the full width (about one fifth of the total height); directly under it a dark metal bracket bar; from the bracket two SHORT chains (only about one eighth of the total height) hold a big horizontal rectangular signboard that fills the lower 60 percent of the height and spans nearly the full width. The signboard is a blank warm orange board with a cream inner border and only one simple centered icon of a skewer of three round brown-red meatballs on a stick, no writing at all. The overall silhouette is a bit taller than wide: 7 wide by 8.6 tall."),
 "step": ("16:9", "Subject: a thick raised stone curb platform block you can stand on, seen in pure front elevation with no perspective. It is a CHUNKY horizontal rectangle exactly 4 units wide and 1 unit tall (height is one quarter of width — think of a thick brick of stone, not a thin plank): a smooth flat cap with slightly rounded top corners and a cream highlight strip along the top edge, warm light grey-beige stone body, one darker cel-shade band along the lower third, and two thin vertical seams dividing it into three equal blocks. No spots, no cracks."),
}
for k in (sys.argv[1:] or list(P)):
    ar, body = P[k]
    req = {"command": "image.generate", "args": [{"prompt": PREFIX + " " + body + TAIL, "model": "gpt-image-2.5-flare", "quality": "medium", "aspectRatio": ar, "imageSize": "2K", "background": "transparent", "name": k + "_v3"}]}
    with open(os.path.join(D, k + "_v3.json"), "w", encoding="utf-8") as f:
        json.dump(req, f, ensure_ascii=False)
print("ok")
